uniform float amzp_offsetX;
uniform float amzp_offsetY;
uniform float amzp_scaleX;
uniform float amzp_lockToScaleX;
uniform float amzp_scaleY;
uniform float amzp_rotation;
uniform float amzp_detail;
uniform float amzp_coarseness;
uniform float amzp_mutation;
uniform float amzp_brightness;
uniform float amzp_contrast;
uniform float amzp_redBalance;
uniform float amzp_greenBalance;
uniform float amzp_blueBalance;
