        float hash(float2 p) {
            return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
        }

        float3 hash3(float2 p) {
            float3 q = float3(
                dot(p, float2(127.1, 311.7)),
                dot(p, float2(269.5, 183.3)),
                dot(p, float2(419.2, 371.9))
            );
            return fract(sin(q) * 43758.5453);
        }


        float vnoise(float2 p) {
            float2 i = floor(p);
            float2 f = fract(p);
            f = f * f * (3.0 - 2.0 * f);
            float a = hash(i);
            float b = hash(i + float2(1.0, 0.0));
            float c = hash(i + float2(0.0, 1.0));
            float d = hash(i + float2(1.0, 1.0));
            return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
        }





        float3 colorNoise(float2 p) {
            float r = vnoise(p + float2(0.0,    0.0   ));
            float g = vnoise(p + float2(5.2,    1.3   ));
            float b = vnoise(p + float2(10.4,   2.6   ));
            return float3(r, g, b);
        }



        float3 fbmColor(float2 p, float detailAmt) {
            int octaves = int(clamp(detailAmt / 100.0 * 7.0 + 1.0, 1.0, 8.0));
            float3 v   = float3(0.0);
            float amp  = 0.5;
            float freq = 1.0;
            for (int i = 0; i < 8; i++) {
                if (i >= octaves) break;
                v   += amp * colorNoise(p * freq);
                freq *= 2.0;
                amp  *= 0.5;
            }
            return v;
        }


        float luma(float3 c) {
            return dot(c, float3(0.2126, 0.7152, 0.0722));
        }


