            float mx = max(c.r, max(c.g, c.b));
            float mn = min(c.r, min(c.g, c.b));
            float d  = mx - mn;
            float l  = (mx + mn) * 0.5;
            float s  = 0.0;
            float h  = 0.0;
            if (d > 0.0001) {
                s = d / (1.0 - abs(2.0 * l - 1.0));
                if      (mx == c.r) h = mod((c.g - c.b) / d, 6.0);
                else if (mx == c.g) h = (c.b - c.r) / d + 2.0;
                else                h = (c.r - c.g) / d + 4.0;
                h /= 6.0;
            }
            return float3(h, s, l);
        }

        float3 hsl2rgb(float3 hsl) {
            float h = hsl.x; float s = hsl.y; float l = hsl.z;
            float c2 = (1.0 - abs(2.0 * l - 1.0)) * s;
            float x  = c2 * (1.0 - abs(mod(h * 6.0, 2.0) - 1.0));
            float m  = l - c2 * 0.5;
            float3 rgb;
            if      (h < 1.0/6.0) rgb = float3(c2, x,  0.0);
            else if (h < 2.0/6.0) rgb = float3(x,  c2, 0.0);
            else if (h < 3.0/6.0) rgb = float3(0.0, c2, x);
            else if (h < 4.0/6.0) rgb = float3(0.0, x,  c2);
            else if (h < 5.0/6.0) rgb = float3(x,  0.0, c2);
            else                   rgb = float3(c2, 0.0, x);
            return clamp(rgb + m, 0.0, 1.0);
        }



        float3 applyBlend(float3 base, float3 blend2, int mode) {
            if (mode == 0)  return blend2;                                          
            if (mode == 1)  return base + blend2;                                   
            if (mode == 2)  return base * blend2;                                   
            if (mode == 3)  return 1.0 - (1.0 - base) * (1.0 - blend2);           
            if (mode == 4)  return mix(                                             
                                2.0 * base * blend2,
                                1.0 - 2.0 * (1.0 - base) * (1.0 - blend2),
                                step(0.5, base));
            if (mode == 5) {                                                        
                float3 d = mix(2.0 * base * blend2 + base * base * (1.0 - 2.0 * blend2),
                             sqrt(base) * (2.0 * blend2 - 1.0) + 2.0 * base * (1.0 - blend2),
                             step(0.5, blend2));
                return d;
            }
            if (mode == 6)  return mix(                                             
                                2.0 * base * blend2,
                                1.0 - 2.0 * (1.0 - base) * (1.0 - blend2),
                                step(0.5, blend2));
