            if (mode == 8)  return 1.0 - (1.0 - base) / max(blend2, 0.001);       
            if (mode == 9)  return min(base, blend2);                              
            if (mode == 10) return max(base, blend2);                              
            if (mode == 11) return abs(base - blend2);                             
            if (mode == 12) return base + blend2 - 2.0 * base * blend2;           
            if (mode == 13) {                                                       
                float3 baseHSL  = rgb2hsl(base);
                float3 blendHSL = rgb2hsl(blend2);
                return hsl2rgb(float3(blendHSL.x, baseHSL.y, baseHSL.z));
            }
            if (mode == 14) {                                                       
                float3 baseHSL  = rgb2hsl(base);
                float3 blendHSL = rgb2hsl(blend2);
                return hsl2rgb(float3(baseHSL.x, blendHSL.y, baseHSL.z));
            }
            if (mode == 15) {                                                       
                float3 baseHSL  = rgb2hsl(base);
                float3 blendHSL = rgb2hsl(blend2);
                return hsl2rgb(float3(blendHSL.x, blendHSL.y, baseHSL.z));
            }
            if (mode == 16) {                                                       
                float3 baseHSL  = rgb2hsl(base);
                float3 blendHSL = rgb2hsl(blend2);
                return hsl2rgb(float3(baseHSL.x, baseHSL.y, blendHSL.z));
            }
            return blend2;
        }

        void amzRender() {
            float2 uv    = amzScreenNorm();
            float4 src   = amzTexture(0, uv);
            float3 srcCol = src.rgb;
            float srcAlpha = src.a;





            float2 noiseUV = uv;


            noiseUV -= float2(amzp_offsetX, amzp_offsetY) / screen.zw;


            float2 centred = noiseUV - float2(0.5);
            float rad    = radians(amzp_rotation);
            float cosR   = cos(rad);
            float sinR   = sin(rad);
            centred = float2(centred.x * cosR - centred.y * sinR,
                           centred.x * sinR + centred.y * cosR);
            noiseUV = centred + float2(0.5);



            float sY = mix(amzp_scaleY, amzp_scaleX, step(0.5, amzp_lockToScaleX));
            noiseUV  = (noiseUV - 0.5) / float2(max(amzp_scaleX, 0.001), max(sY, 0.001)) + 0.5;




            float freq = mix(0.5, 20.0, amzp_coarseness / 100.0);



            float mutTime = time * amzp_mutation * 0.15;


            float2 noiseCoord = noiseUV * freq + float2(mutTime);
            float3 noiseCol   = fbmColor(noiseCoord, amzp_detail);



            noiseCol.r = clamp(noiseCol.r + amzp_redBalance   / 200.0, 0.0, 1.0);
            noiseCol.g = clamp(noiseCol.g + amzp_greenBalance / 200.0, 0.0, 1.0);
            noiseCol.b = clamp(noiseCol.b + amzp_blueBalance  / 200.0, 0.0, 1.0);



            float bright = amzp_brightness / 200.0;

            float cont   = mix(0.5, 2.5, (amzp_contrast + 100.0) / 200.0);
            noiseCol     = (noiseCol - 0.5) * cont + 0.5 + bright;
            noiseCol     = clamp(noiseCol, 0.0, 1.0);


            float3 blended = applyBlend(srcCol, noiseCol, int(amzp_applyMode));
            blended      = clamp(blended, 0.0, 1.0);


            blended = mix(srcCol, blended, amzp_applyMix);


            blended = mix(srcCol, blended, amzp_opacity);

            float outAlpha = srcAlpha;


            float alphaMask = step(0.5, amzp_useSourceAlpha);
            blended  = mix(blended, blended * srcAlpha, alphaMask);
            outAlpha = mix(1.0, srcAlpha, alphaMask);


            float3 result = mix(srcCol, blended, amzp_blend);
            result      = clamp(result, 0.0, 1.0);

            amzOutput = float4(result, outAlpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

